mapper.select:
SELECT b.box_id as boxId, b.box_number as boxNumber, s.series_id as seriesId, s.series_name as seriesName FROM product_box b LEFT JOIN product_series s ON b.series_id = s.series_id WHERE 1=1
AND b.box_id = #{boxId}
AND b.series_id = #{seriesId}
AND s.series_name LIKE CONCAT('%', #{seriesName}, '%')
ORDER BY b.box_id

mapper.delete:
DELETE FROM product_box
WHERE box_id = #{boxId}
and box_number = #{boxNumber}
